style.css:
@-moz-document url-prefix("http://"), url-prefix("https://") {
html, body {
    height: 100%;
    margin: 0;
    background: transparent !important;
  }

  /* Background GIF */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    background-image: url("https://giffiles.alphacoders.com/196/196631.gif");
    background-size: cover;
    background-position: center center;
    background-repeat: no-repeat;
    z-index: -9999;     /* keeps it behind everything */
    opacity: 0.8;       /* controls GIF visibility */
    pointer-events: none;
  }

  body::after {
    content: "";
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.45); /* adjust 0.45 for lighter/darker overlay */
    z-index: -9998;
    pointer-events: none;
  }
}
